mapper.select:
/* com.portal.user.help.qna.QnaManageMapper.selectQnaList */ SELECT a.QA_ID AS qaId, a.QESTN_SJ AS qestnSj, a.QESTN_CN AS qestnCn, a.WRITNG_PASSWORD AS writngPassword, a.AREA_NO AS areaNo, a.MIDDLE_TELNO AS middleTelno, a.END_TELNO AS endTelno, a.EMAIL_ADRES AS emailAdres, a.EMAIL_ANSWER_AT AS emailAnswerAt, a.WRTER_NM AS wrterNm, a.WRITNG_DE AS writngDe, a.ANSWER_CN AS answerCn, a.ANSWER_DE AS answerDe, a.RDCNT AS inqireCo, a.QNA_PROCESS_STTUS_CODE AS qnaProcessSttusCode, b.CODE_NM AS qnaProcessSttusCodeNm, DATE_FORMAT(a.FRST_REGIST_PNTTM, '%Y-%m-%d') AS frstRegisterPnttm, a.FRST_REGISTER_ID AS frstRegisterId, DATE_FORMAT(a.LAST_UPDT_PNTTM, '%Y-%m-%d') AS lastUpdusrPnttm, a.LAST_UPDUSR_ID AS lastUpdusrId FROM LETTNQAINFO a LEFT OUTER JOIN LETTCCMMNDETAILCODE b ON b.CODE_ID = 'COM028' AND a.QNA_PROCESS_STTUS_CODE = b.CODE WHERE 1 = 1
AND a.WRTER_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND a.QESTN_SJ LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY a.QA_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

/* com.portal.user.help.qna.QnaManageMapper.selectQnaListTotCnt */ SELECT COUNT(*) AS totcnt FROM LETTNQAINFO WHERE 1 = 1
AND WRTER_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND QESTN_SJ LIKE CONCAT('%', #{searchKeyword}, '%')

mapper.update:
/* com.portal.user.help.qna.QnaManageMapper.updateQnaInqireCo */
UPDATE LETTNQAINFO
   SET RDCNT = IFNULL(RDCNT, 0) + 1
 WHERE QA_ID = #{qaId}

mapper.select:
/* com.portal.user.help.qna.QnaManageMapper.selectQnaPasswordConfirmCnt */
SELECT COUNT(*) AS totcnt
  FROM LETTNQAINFO
 WHERE QA_ID           = #{qaId}
   AND WRITNG_PASSWORD = #{writngPassword}

/* com.portal.user.help.qna.QnaManageMapper.selectQnaAnswerList */ SELECT a.QA_ID AS qaId, a.QESTN_SJ AS qestnSj, a.QESTN_CN AS qestnCn, a.WRITNG_PASSWORD AS writngPassword, a.AREA_NO AS areaNo, a.MIDDLE_TELNO AS middleTelno, a.END_TELNO AS endTelno, a.EMAIL_ADRES AS emailAdres, a.EMAIL_ANSWER_AT AS emailAnswerAt, a.WRTER_NM AS wrterNm, a.WRITNG_DE AS writngDe, a.ANSWER_CN AS answerCn, a.ANSWER_DE AS answerDe, a.RDCNT AS inqireCo, a.QNA_PROCESS_STTUS_CODE AS qnaProcessSttusCode, b.CODE_NM AS qnaProcessSttusCodeNm, DATE_FORMAT(a.FRST_REGIST_PNTTM, '%Y-%m-%d') AS frstRegisterPnttm, a.FRST_REGISTER_ID AS frstRegisterId, DATE_FORMAT(a.LAST_UPDT_PNTTM, '%Y-%m-%d') AS lastUpdusrPnttm, a.LAST_UPDUSR_ID AS lastUpdusrId FROM LETTNQAINFO a LEFT OUTER JOIN LETTCCMMNDETAILCODE b ON b.CODE_ID = 'COM028' AND a.QNA_PROCESS_STTUS_CODE = b.CODE WHERE 1 = 1
AND a.WRTER_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND b.CODE_NM LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY a.QA_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

/* com.portal.user.help.qna.QnaManageMapper.selectQnaAnswerListTotCnt */ SELECT COUNT(*) AS totcnt FROM LETTNQAINFO a LEFT OUTER JOIN LETTCCMMNDETAILCODE b ON b.CODE_ID = 'COM028' AND a.QNA_PROCESS_STTUS_CODE = b.CODE WHERE 1 = 1
AND a.WRTER_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND b.CODE_NM LIKE CONCAT('%', #{searchKeyword}, '%')

mapper.update:
/* com.portal.user.help.qna.QnaManageMapper.updateQnaCnAnswer */
UPDATE LETTNQAINFO
   SET QNA_PROCESS_STTUS_CODE = #{qnaProcessSttusCode},
       ANSWER_CN              = #{answerCn},
       ANSWER_DE              = DATE_FORMAT(SYSDATE(), '%Y%m%d'),
       LAST_UPDT_PNTTM        = SYSDATE(),
       LAST_UPDUSR_ID         = #{lastUpdusrId}
 WHERE QA_ID                  = #{qaId}
